        value: ID
    }
    plugin-appearance {
        stackOnMobile: true
    }
    rowSelection {
        type: singleSelection
        currentSelectionPageItem: P2_SELECTED_EMPLOYEE
    }
    pagination {
        type: page
        entitiesPerPage: 50
    }
    column ID (
        source {
            databaseColumn: ID
            dataType: number
            primaryKey: true
        }
    )
    column NAME (
        source { databaseColumn: NAME dataType: varchar2 }
    )
    column JOB (
        source { databaseColumn: JOB dataType: varchar2 }
    )
