        displayAvatar: true
        displayBadge: true
    }
    plugin-avatar {
        type: initials
        initials: INITIALS
    }
    plugin-badge {
        label: ID
        value: ID
    }
    plugin-appearance {
        stackOnMobile: true
    }
    rowSelection {
        type: multipleSelection
        currentSelectionPageItem: P2_SELECTED_EMPLOYEE
        selectAllPageItem: P2_SELECT_ALL
    }
    pagination {
        type: page
        entitiesPerPage: 50
    }
    column ID (
        source {
            databaseColumn: ID
            dataType: number
            primaryKey: true
        }
